// Stand-in for @minecraft/server, enough to run the DLC tools offline.
// Block states come from defs.json (gen_defs.py).
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
const here = path.dirname(fileURLToPath(import.meta.url));
const DEF = JSON.parse(fs.readFileSync(process.env.ARC_DEFS ?? path.join(here, '../../../defs.json'), 'utf8'));
const perms = new Map();
export class BlockPermutation {
  constructor(id, states) { this.id = id; this.states = states; this.type = { id }; }
  static resolve(id, states = {}) {
    if (!id.includes(':')) id = 'minecraft:' + id;
    const d = DEF[id];
    if (!d) throw new Error('unknown block ' + id);
    const out = {};
    for (const [k, vals] of Object.entries(d)) out[k] = vals[0];
    for (const [k, v] of Object.entries(states)) {
      if (!(k in d)) throw new Error(`${id}: unknown state ${k}`);
      if (!d[k].some(x => x === v)) throw new Error(`${id}: bad value ${k}=${JSON.stringify(v)}`);
      out[k] = v;
    }
    // permutations are interned like the real API (same states -> same object)
    const key = id + JSON.stringify(out);
    let p = perms.get(key);
    if (!p) { p = new BlockPermutation(id, out); perms.set(key, p); }
    return p;
  }
  getState(n) { return this.states[n]; }
  getAllStates() { return { ...this.states }; }
  withState(n, v) { return BlockPermutation.resolve(this.id, { ...this.states, [n]: v }); }
  matches(id, states = {}) {
    if (!id.includes(':')) id = 'minecraft:' + id;
    return id === this.id && Object.entries(states).every(([k, v]) => this.states[k] === v);
  }
  getItemStack() { return new ItemStack(this.id); }
}
export const BlockTypes = { get: id => (DEF[id.includes(':') ? id : 'minecraft:' + id] ? { id: id.includes(':') ? id : 'minecraft:' + id } : undefined), getAll: () => Object.keys(DEF).map(id => ({ id })) };
const ev = () => { const subs = []; return { subs, subscribe(f) { subs.push(f); return f; }, unsubscribe() {}, fire(e) { for (const f of subs) f(e); } }; };
const evs = new Proxy({}, { get(t, k) { if (!(k in t)) t[k] = ev(); return t[k]; } });
const aevs = new Proxy({}, { get(t, k) { if (!(k in t)) t[k] = ev(); return t[k]; } });
const sevs = new Proxy({}, { get(t, k) { if (!(k in t)) t[k] = ev(); return t[k]; } });
let timers = [];
export const system = {
  currentTick: 0,
  run(f) { timers.push(f); return timers.length; },
  runTimeout(f) { timers.push(f); return timers.length; },
  runInterval() { return 0; },
  clearRun() {},
  runJob(gen) { for (const _ of gen); return 0; },
  beforeEvents: sevs, afterEvents: {},
  /** test helper: run queued run()/runTimeout() callbacks */
  flush() { for (let i = 0; i < 50 && timers.length; i++) { const t = timers; timers = []; for (const f of t) f(); } },
};
class StructureManagerMock {
  constructor() { this.map = new Map(); }
  createFromWorld(id, dim, from, to, opts = {}) {
    const min = { x: Math.min(from.x, to.x), y: Math.min(from.y, to.y), z: Math.min(from.z, to.z) };
    const max = { x: Math.max(from.x, to.x), y: Math.max(from.y, to.y), z: Math.max(from.z, to.z) };
    const size = { x: max.x - min.x + 1, y: max.y - min.y + 1, z: max.z - min.z + 1 };
    const blocks = new Map();
    for (let x = 0; x < size.x; x++) for (let y = 0; y < size.y; y++) for (let z = 0; z < size.z; z++)
      blocks.set(`${x},${y},${z}`, dim.getBlock({ x: min.x + x, y: min.y + y, z: min.z + z }).permutation);
    const s = { id, size, isValid: () => true, getBlockPermutation: l => blocks.get(`${l.x},${l.y},${l.z}`), saveToWorld() {} };
    this.map.set(id, s);
    return s;
  }
  get(id) { return this.map.get(id); }
  delete(id) { return this.map.delete(id); }
  getWorldStructureIds() { return [...this.map.keys()]; }
  getPackStructureIds() { return []; }
}
const worldDP = new Map();
export const world = {
  beforeEvents: evs, afterEvents: aevs,
  getAllPlayers: () => [],
  getDimension: () => undefined,
  structureManager: new StructureManagerMock(),
  getDynamicProperty: k => worldDP.get(k),
  setDynamicProperty: (k, v) => v === undefined ? worldDP.delete(k) : worldDP.set(k, v),
  getDynamicPropertyIds: () => [...worldDP.keys()],
  sendMessage() {},
};
export const LiquidType = { Water: 'Water' };
export const StructureSaveMode = { World: 'World', Memory: 'Memory' };
export const StructureRotation = { None: 'None', Rotate90: 'Rotate90', Rotate180: 'Rotate180', Rotate270: 'Rotate270' };
export const StructureMirrorAxis = { None: 'None', X: 'X', Z: 'Z', XZ: 'XZ' };
export const CommandPermissionLevel = { Any: 0, GameDirectors: 1, Admin: 2, Host: 3, Owner: 4 };
export const CustomCommandParamType = { Float: 'Float', Boolean: 'Boolean', Integer: 'Integer', String: 'String', Enum: 'Enum', Location: 'Location' };
export const CustomCommandStatus = { Success: 0, Failure: 1 };
export const PlayerPermissionLevel = { Visitor: 0, Member: 1, Operator: 2, Custom: 3 };
export const GameMode = { Creative: 'Creative', Survival: 'Survival' };
export const EquipmentSlot = { Mainhand: 'Mainhand' };
export const Direction = { Up: 'Up', Down: 'Down', North: 'North', South: 'South', East: 'East', West: 'West' };
export class ItemStack {
  constructor(typeId, amount = 1) { this.typeId = typeId.includes(':') ? typeId : 'minecraft:' + typeId; this.amount = amount; this.dp = new Map(); this.nameTag = undefined; this.lore = []; }
  getDynamicProperty(k) { return this.dp.get(k); }
  setDynamicProperty(k, v) { this.dp.set(k, v); }
  setLore(l) { this.lore = l; }
  getLore() { return this.lore; }
}
const key = l => `${l.x},${l.y},${l.z}`;
export class Dimension {
  constructor(id = 'minecraft:overworld') { this.id = id; this.map = new Map(); this.heightRange = { min: -64, max: 320 }; this.particles = []; }
  setBlockPermutation(l, p) { this.map.set(key(l), p); }
  getBlock(l) {
    if (l.y < -64 || l.y >= 320) throw new Error('LocationOutOfWorldBoundariesError');
    return new Block(this, { x: Math.floor(l.x), y: Math.floor(l.y), z: Math.floor(l.z) });
  }
  getTopmostBlock(xz) { for (let y = 319; y >= -64; y--) { const b = this.getBlock({ x: xz.x, y, z: xz.z }); if (!b.isAir) return b; } return undefined; }
  getEntities() { return []; }
  spawnParticle(id, l) { this.particles.push([id, l]); }
  runCommand() { return { successCount: 1 }; }
  /** test helper: count non-air blocks, optionally filtered */
  count(fn = () => true) { let n = 0; for (const [k, p] of this.map) if (p.id !== 'minecraft:air' && fn(k, p)) n++; return n; }
}
export class Block {
  constructor(dim, l) { this.dimension = dim; this.location = { ...l }; this.x = l.x; this.y = l.y; this.z = l.z; }
  get permutation() { return this.dimension.map.get(key(this.location)) ?? BlockPermutation.resolve('minecraft:air'); }
  get typeId() { return this.permutation.id; }
  get type() { return { id: this.typeId }; }
  get isAir() { return this.typeId === 'minecraft:air'; }
  get isLiquid() { return /water|lava/.test(this.typeId); }
  get isWaterlogged() { return false; }
  get isValid() { return true; }
  setWaterlogged() {}
  above(n = 1) { return this.offset({ x: 0, y: n, z: 0 }); }
  below(n = 1) { return this.offset({ x: 0, y: -n, z: 0 }); }
  offset(o) { return new Block(this.dimension, { x: this.x + o.x, y: this.y + o.y, z: this.z + o.z }); }
  setPermutation(p) { this.dimension.setBlockPermutation(this.location, p); }
  setType(id) { this.setPermutation(BlockPermutation.resolve(id)); }
  matches(id, st) { return this.permutation.matches(id, st); }
}
/** test helper: a fake player */
export function mockPlayer(dim, opts = {}) {
  const msgs = [];
  const dp = new Map();
  const inv = new Array(36).fill(undefined);
  return {
    id: opts.id ?? 'p1', name: 'Tester', typeId: 'minecraft:player', dimension: dim,
    location: opts.location ?? { x: 0.5, y: 0, z: 0.5 }, rotation: opts.rotation ?? { x: 0, y: 0 },
    selectedSlotIndex: 0, isSneaking: false, msgs, inv,
    sendMessage(m) { msgs.push(typeof m === 'string' ? m : JSON.stringify(m)); },
    onScreenDisplay: { setActionBar(m) { msgs.push('[bar] ' + m); } },
    getRotation() { return this.rotation; },
    getViewDirection() { const r = this.rotation; const ya = r.y * Math.PI / 180, pa = r.x * Math.PI / 180; return { x: -Math.sin(ya) * Math.cos(pa), y: -Math.sin(pa), z: Math.cos(ya) * Math.cos(pa) }; },
    getHeadLocation() { return { x: this.location.x, y: this.location.y + 1.62, z: this.location.z }; },
    getBlockFromViewDirection() { return this.lookAt ? { block: this.dimension.getBlock(this.lookAt), face: 'Up', faceLocation: { x: 0.5, y: 1, z: 0.5 } } : undefined; },
    getDynamicProperty: k => dp.get(k), setDynamicProperty: (k, v) => dp.set(k, v),
    getComponent(n) { if (n === 'minecraft:inventory' || n === 'inventory') return { container: { size: 36, getItem: i => inv[i], setItem: (i, it) => { inv[i] = it; }, addItem: it => { inv[inv.indexOf(undefined)] = it; } } }; return undefined; },
    getGameMode() { return 'Creative'; },
    playSound() {},
    isValid: true,
    hasTag: () => false,
    runCommand: () => ({ successCount: 1 }),
  };
}
